content:
Launcher3 核心架构源码精读
源码基线 aosp-r4，路径 packages/apps/Launcher3/src/com/android/launcher3/。本文精读六个核心类：Launcher、LauncherAppState、LauncherModel、LauncherProvider、ModelDbController、InvariantDeviceProfile，以及它们依赖的 LoaderTask、BgDataModel、DatabaseHelper、LauncherSettings。本仓库已用 Dagger Hilt 风格依赖注入替代旧版的全局单例门面，LauncherAppState 退化为标了 @Deprecated 的 data class，DB 管理从 LauncherProvider 下沉到 ModelDbController。所有代码块均为真实源码裁剪，逐行注中文。
Launcher.java 主 Activity 与总控Launcher 继承 StatefulActivity&lt;LauncherState&gt;，实现 BgDataModel.Callbacks 和 InvariantDeviceProfile.OnIDPChangeListener。它是 MVC 的 View + Controller 合体：持有整个 View 树（Workspace &#x2F; Hotseat &#x2F; AllApps &#x2F; DragLayer），同时通过 Callbacks 接收 Model 层数据。
// Launcher.javapublic class Launcher extends StatefulActivity&lt;LauncherState&gt;        implements Callbacks, InvariantDeviceProfile.OnIDPChangeListener,                LauncherOverlayCallbacks, ... &#123;

onCreate 按顺序做了哪些事onCreate 是启动主链路，每一步顺序敏感。下面是源码裁剪，保留真实调用顺序：
// Launcher.java onCreate (第 436 行起)@Overrideprotected void onCreate(Bundle savedInstanceState) &#123;    TraceHelper.INSTANCE.beginSection(ON_CREATE_EVT);          // 开 systrace 段, 测启动耗时    super.onCreate(savedInstanceState);    mWallpaperThemeManager = new WallpaperThemeManager(this);  // 取壁纸主色驱动主题    LauncherAppState app = LauncherAppState.getInstance(this); // 拿依赖聚合壳(Dagger 注入)    mModel = app.getModel();                                   // 取全局 LauncherModel    mRotationHelper = new RotationHelper(this);               // 旋转控制    InvariantDeviceProfile idp = app.getInvariantDeviceProfile();    initDeviceProfile(idp);                                    // 计算本机 DeviceProfile + 建 ModelWriter    idp.addOnChangeListener(this);                            // 注册 IDP 变化回调    mSharedPrefs = LauncherPrefs.getPrefs(this);    mAccessibilityDelegate = createAccessibilityDelegate();    initDragController();                                      // 建拖拽控制器    mAllAppsController = new AllAppsTransitionController(this);    mStateManager = new StateManager&lt;&gt;(this, NORMAL);          // 状态机, 初始 NORMAL(桌面)    mAppWidgetManager = new WidgetManagerHelper(this);    mAppWidgetHolder = LauncherWidgetHolder.newInstance(this); // Widget 宿主    mAppWidgetHolder.setAppWidgetRemovedCallback(            appWidgetId -&gt; getWorkspace().removeWidget(appWidgetId));    setupViews();                                              // inflate launcher.xml, 组装 View 树    updateDisallowBack();    mAppWidgetHolder.startListening();                         // 开始监听 Widget 更新    mAppWidgetHolder.addProviderChangeListener(            () -&gt; refreshAndBindWidgetsForPackageUser(null));    mWidgetVisibilityTracker = new WidgetVisibilityTracker(this, mAppWidgetHolder, mWorkspace,        mStateManager);    // ... PopupController / WidgetPickerDataProvider / SystemDragController 初始化 ...    boolean internalStateHandled = ACTIVITY_TRACKER.handleCreate(this); // 处理外部拉起的目标状态    restoreState(savedInstanceState);                          // 从 savedInstanceState 恢复状态    mStateManager.reapplyState();                              // 把状态机的状态重新应用到 UI    if (savedInstanceState != null) &#123;        int[] pageIds = savedInstanceState.getIntArray(RUNTIME_STATE_CURRENT_SCREEN_IDS);        if (pageIds != null) &#123;            mModelCallbacks.setPagesToBindSynchronously(IntSet.wrap(pageIds)); // 告诉 Model 哪些屏要同步 bind        &#125;    &#125;    // 核心握手: 把自己注册为 Callbacks 并触发数据加载    if (!mModel.addCallbacksAndLoad(this)) &#123;                   // 返回 false = 没同步 bind, 走异步        if (!internalStateHandled) &#123;            // 数据没就绪, 暂停绘制, 让系统继续显示 loading 提示            mOnInitialBindListener = Boolean.FALSE::booleanValue;        &#125;    &#125;    setContentView(getRootView());                             // 设置根 View    if (mOnInitialBindListener != null) &#123;        // 挂在 ViewTreeObserver 上, 首次 bind 完成前拦截 onPreDraw, 不绘制        getRootView().getViewTreeObserver().addOnPreDrawListener(mOnInitialBindListener);    &#125;    getRootView().dispatchInsets();    // ... SettingsCache / ScreenOnTracker / OverlayManager 注册 ...    mOverlayManager = getDefaultOverlay();                     // 默认空 Overlay(-1 屏/feed)    mRotationHelper.initialize();    getWindow().setSoftInputMode(LayoutParams.SOFT_INPUT_ADJUST_NOTHING);&#125;

addCallbacksAndLoad(this) 返回值的语义是整个启动时序的关键：返回 true 表示数据已加载且已同步 bind（快路径，桌面立即可见）；返回 false 表示数据未就绪，Model 启动了 LoaderTask 异步加载。异步路径下，mOnInitialBindListener 返回 false 拦截 onPreDraw，使首帧延迟到首次 bind 完成，避免显示空白桌面。
initDeviceProfile 的真实实现：
// Launcher.java initDeviceProfile (第 724 行)protected boolean initDeviceProfile(InvariantDeviceProfile idp) &#123;    DeviceProfile deviceProfile = idp.getDeviceProfile(this);  // 根据当前屏幕从 supportedProfiles 选一个    if (mDeviceProfile == deviceProfile) &#123;        return false;                                          // 没变化(重建时复用)    &#125;    mDeviceProfile = deviceProfile;    // 坐标映射器: 模型坐标(screenId/cellX/cellY) ↔ 视图坐标    // 双屏折叠用 TwoPanelCellPosMapper, 普通用 CellPosMapper    if (FOLDABLE_SINGLE_PAGE.get() &amp;&amp; mDeviceProfile.getDeviceProperties().isTwoPanels()) &#123;        mCellPosMapper = new TwoPanelCellPosMapper(mDeviceProfile.inv.numColumns);    &#125; else &#123;        mCellPosMapper = new CellPosMapper(mDeviceProfile.isVerticalBarLayout(),                mDeviceProfile.numShownHotseatIcons);    &#125;    mModelWriter = mModel.getWriter(true, mCellPosMapper, this); // 拿写库入口(拖拽后写回用)    updateFixedLandscape();    return true;&#125;

setupViews 组装 View 树// Launcher.java setupViews (第 1275 行)protected void setupViews() &#123;    if (allAppsBlur()) &#123;        getTheme().applyStyle(getAllAppsBlurStyleResId(), true); // AllApps 毛玻璃主题    &#125;    inflateRootView(R.layout.launcher);                        // inflate launcher.xml    mDragLayer = findViewById(R.id.drag_layer);                // 拖拽层, 所有内容的容器    mFocusHandler = mDragLayer.getFocusIndicatorHelper();    mWorkspace = mDragLayer.findViewById(R.id.workspace);      // 工作区(多页桌面)    mWorkspace.initParentViews(mDragLayer);    mOverviewPanel = findViewById(R.id.overview_panel);        // Overview 面板    mHotseat = findViewById(R.id.hotseat);                     // 底部快捷栏    mHotseat.setWorkspace(mWorkspace);    mLeftArrow = findViewById(R.id.left_indicator_arrow);      // 翻页箭头    mRightArrow = findViewById(R.id.right_indicator_arrow);    mDragLayer.setup(mDragController, mWorkspace);    mWorkspace.setup(mDragController);    mWorkspace.lockWallpaperToDefaultPage();                   // bind 前锁壁纸偏移, 避免 RTL 错位    mWorkspace.bindAndInitFirstWorkspaceScreen();              // 建第一屏(含 QSB 占位)    mDragController.addDragListener(mWorkspace);    mDropTargetBar = mDragLayer.findViewById(R.id.drop_target_bar); // 删除/卸载/信息 拖放目标栏    mAppsView = findViewById(R.id.apps_view);                  // AllApps 容器    mAppsView.setAllAppsTransitionController(mAllAppsController);    mScrimView = findViewById(R.id.scrim_view);                // 背景遮罩    mDropTargetBar.setup(mDragController);    mAllAppsController.setupViews(mScrimView, mAppsView);    mItemInflater = new ItemInflater&lt;&gt;(this, mAppWidgetHolder, getItemOnClickListener(),            mFocusHandler, new CellLayout(mWorkspace.getContext(), mWorkspace));&#125;

onResume &#x2F; onPause &#x2F; onNewIntent 实际逻辑// Launcher.java onResume (第 1203 行)@Overrideprotected void onResume() &#123;    super.onResume();    if (mDeferOverlayCallbacks) &#123;        scheduleDeferredCheck();                               // Overlay 回调延后(启动早期)    &#125; else &#123;        mOverlayManager.onActivityResumed();    &#125;    DragView.removeAllViews(this);                             // 清残留 DragView&#125;@Overrideprotected void onPause() &#123;    // 暂停期间新装的 App 先排队, resume 时再推到桌面    ItemInstallQueue.INSTANCE.get(this).pauseModelPush(FLAG_ACTIVITY_PAUSED);    super.onPause();    mDragController.cancelDrag();                              // 取消进行中的拖拽    mLastTouchUpTime = -1;    mDropTargetBar.animateToVisibility(false);                 // 隐藏删除栏    if (!mDeferOverlayCallbacks) &#123;        mOverlayManager.onActivityPaused();    &#125;    mAppWidgetHolder.setActivityResumed(false);&#125;

真正的 resume 后处理在 onDeferredResumed（等空闲后执行）：
// Launcher.java onDeferredResumed (第 1021 行)@Overrideprotected void onDeferredResumed() &#123;    logStopAndResume(true /* isResume */);    ItemInstallQueue.INSTANCE.get(this).resumeModelPush(FLAG_ACTIVITY_PAUSED); // 把排队的新 App 推入桌面    mModel.validateModelDataOnResume();                        // 校验快捷方式权限是否变化    DiscoveryBounce.showForHomeIfNeeded(this);                 // 引导动画    mAppWidgetHolder.setActivityResumed(true);&#125;

onNewIntent 处理 HOME 键、ALL_APPS intent 等。关键变量 alreadyOnHome：判断是否已有窗口焦点且不是 BROUGHT_TO_FRONT，决定要不要把当前屏滑回默认屏。
// Launcher.java onNewIntent (第 1539 行)@Overrideprotected void onNewIntent(Intent intent) &#123;    super.onNewIntent(intent);    boolean alreadyOnHome = hasWindowFocus() &amp;&amp; ((intent.getFlags()            &amp; Intent.FLAG_ACTIVITY_BROUGHT_TO_FRONT) != Intent.FLAG_ACTIVITY_BROUGHT_TO_FRONT);    boolean shouldMoveToDefaultScreen = alreadyOnHome &amp;&amp; isInState(NORMAL)            &amp;&amp; AbstractFloatingView.getTopOpenView(this) == null;    boolean isActionMain = Intent.ACTION_MAIN.equals(intent.getAction());    boolean internalStateHandled = ACTIVITY_TRACKER.handleNewIntent(this);    if (isActionMain) &#123;        if (!internalStateHandled) &#123;            AbstractFloatingView.closeAllOpenViewsExcept(this, isStarted(), ...); // 关浮层            if (!isInState(NORMAL)) &#123;                mStateManager.goToState(NORMAL, mStateManager.shouldAnimateStateChange());            &#125;            if (!alreadyOnHome) &#123;                mAppsView.reset(mStateManager.shouldAnimateStateChange(), false);            &#125;            if (shouldMoveToDefaultScreen &amp;&amp; !mWorkspace.isHandlingTouch()) &#123;                mWorkspace.post(mWorkspace::moveToDefaultScreen); // 回到默认屏            &#125;        &#125;        mOverlayManager.hideOverlay(isStarted());    &#125; else if (Intent.ACTION_ALL_APPS.equals(intent.getAction())) &#123;        showAllAppsFromIntent(alreadyOnHome);    &#125; else if (INTENT_ACTION_ALL_APPS_TOGGLE.equals(intent.getAction())) &#123;        toggleAllApps(alreadyOnHome, true);    &#125; else if (Intent.ACTION_SHOW_WORK_APPS.equals(intent.getAction())) &#123;        showAllAppsWithSelectedTabFromIntent(alreadyOnHome, ...WORK);    &#125;&#125;

状态恢复 onSaveInstanceState// Launcher.java onSaveInstanceState (第 1680 行)@Overrideprotected void onSaveInstanceState(Bundle outState) &#123;    outState.putIntArray(RUNTIME_STATE_CURRENT_SCREEN_IDS,             // 当前各屏 screenId            mWorkspace.getCurrentPageScreenIds().getArray().toArray());    outState.putInt(RUNTIME_STATE, mStateManager.getState().ordinal);  // 状态机序号(NORMAL/ALL_APPS...)    AbstractFloatingView widgets = AbstractFloatingView            .getOpenView(this, AbstractFloatingView.TYPE_WIDGETS_FULL_SHEET);    if (widgets != null) &#123;        SparseArray&lt;Parcelable&gt; widgetsState = new SparseArray&lt;&gt;();        widgets.saveHierarchyState(widgetsState);                       // Widget 选择面板状态        outState.putSparseParcelableArray(RUNTIME_STATE_WIDGET_PANEL, widgetsState);    &#125;    // 关闭非 rebind-safe 的浮层(打开的文件夹等), 避免重建后状态错乱    AbstractFloatingView.closeAllOpenViewsExcept(this, isStarted() &amp;&amp; !isForceInvisible(), TYPE_REBIND_SAFE);    if (mPendingRequestArgs != null) &#123;        outState.putParcelable(RUNTIME_STATE_PENDING_REQUEST_ARGS, mPendingRequestArgs); // 待处理添加请求    &#125;    outState.putInt(RUNTIME_STATE_PENDING_REQUEST_CODE, mPendingActivityRequestCode);    if (mPendingActivityResult != null) &#123;        outState.putParcelable(RUNTIME_STATE_PENDING_ACTIVITY_RESULT, mPendingActivityResult);    &#125;    super.onSaveInstanceState(outState);&#125;

RUNTIME_STATE_CURRENT_SCREEN_IDS 恢复后传给 mModelCallbacks.setPagesToBindSynchronously，让 LoaderTask 优先同步绑定用户当前看的屏，加速首屏可见。
onDestroy 解绑// Launcher.java onDestroy (第 1714 行)@Overridepublic void onDestroy() &#123;    super.onDestroy();    ACTIVITY_TRACKER.onContextDestroyed(this);    SettingsCache.INSTANCE.get(this).unregister(TOUCHPAD_NATURAL_SCROLLING, mNaturalScrollingChangedListener);    ScreenOnTracker.INSTANCE.get(this).removeListener(mScreenOnListener);    PluginManagerWrapper.INSTANCE.get(this).removePluginListener(this);    mModel.removeCallbacks(this);                              // 从 Model 注销, 不再收 bind    mRotationHelper.destroy();    mAppWidgetHolder.stopListening();    mAppWidgetHolder.destroy();    mWidgetVisibilityTracker.destroy();    mModelCallbacks.clearPendingBinds();                       // 丢弃未处理的 bind    LauncherAppState.getIDP(this).removeOnChangeListener(this);    mOverlayManager.onActivityDestroyed();&#125;

onIdpChanged 配置变化// Launcher.java onIdpChanged / onHandleConfigurationChanged (第 674 行)@Overridepublic void onIdpChanged(boolean modelPropertiesChanged) &#123;    onHandleConfigurationChanged();&#125;@Overrideprotected void onHandleConfigurationChanged() &#123;    Trace.beginSection(&quot;Launcher#onHandleconfigurationChanged&quot;);    try &#123;        if (!initDeviceProfile(mDeviceProfile.inv)) &#123;          // DeviceProfile 没变就不处理            return;        &#125;        dispatchDeviceProfileChanged();        reapplyUi();                                           // 重新应用主题        mDragLayer.recreateControllers();        onSaveInstanceState(new Bundle());                     // 初始化 listWidgets 静态缓存        mModel.rebindCallbacks();                              // 重新跑 LoaderTask 把新网格数据 bind        updateDisallowBack();    &#125; finally &#123;        Trace.endSection();    &#125;&#125;

Launcher 接收数据的 Callbacks 转发Launcher 实现了 Callbacks，但几乎所有 bind* 方法都转交给 mModelCallbacks（ModelCallbacks 对象）。Launcher 只负责生命周期与状态，数据→视图的具体填充被抽到 ModelCallbacks。
面试深问为什么 onCreate 里要先 addCallbacksAndLoad 再 setContentView？顺序无关绑定时机（Callback 只是注册），但 mOnInitialBindListener 必须在 setContentView 后挂到 ViewTreeObserver。真正原因是 addCallbacksAndLoad 可能触发同步 bind，此时 View 树已建好（setupViews 已 inflate），数据才能直接灌进去。
为什么 onPause 要 pauseModelPush？Launcher 不可见时新装的 App 不该立刻出现在桌面（用户看不到，且可能打断正在进行的拖拽）。ItemInstallQueue 把这些安装事件排队，onDeferredResumed 时统一 resumeModelPush 批量推入，减少重复 bind。
mOnInitialBindListener 拦截绘制为什么不会卡死？它是 OnPreDrawListener 返回 false，在首次 bind 完成后会被移除并触发重绘。Boolean.FALSE::booleanValue 是方法引用，首次 bind 完成调用 clearPendingBinds&#x2F;finishBindingItems 时会把它置空并 removeOnPreDrawListener。
LauncherAppState.kt 已废弃的依赖聚合壳// LauncherAppState.kt (完整 48 行)@Deprecated(&quot;Inject the specific targets directly instead of using LauncherAppState&quot;)data class LauncherAppState@Injectconstructor(    @ApplicationContext val context: Context,    val iconProvider: LauncherIconProvider,    val iconCache: IconCache,    val model: LauncherModel,    val invariantDeviceProfile: InvariantDeviceProfile,    @Named(&quot;SAFE_MODE&quot;) val isSafeModeEnabled: Boolean,) &#123;    companion object &#123;        @JvmField var INSTANCE = DaggerSingletonObject &#123; it.launcherAppState &#125;        @JvmStatic fun getInstance(context: Context) = INSTANCE[context]        @JvmStatic fun getIDP(context: Context) = InvariantDeviceProfile.INSTANCE[context]    &#125;&#125;

为什么废弃，现在怎么注入旧版 AOSP 里 LauncherAppState 是”上帝对象”单例：它 new LauncherModel()、new IconCache()、注册包广播，所有核心依赖都从它取。问题：单例硬编码依赖，无法替换、难测试、循环依赖风险高。
当前实现：@Inject constructor + Dagger。所有依赖（IconCache、LauncherModel、InvariantDeviceProfile、ModelDbController…）都标 @LauncherAppSingleton，由 Dagger 组件管理生命周期。LauncherAppState 退化成 data class，只是把一组常用依赖打包，方便 Launcher.onCreate 一行 LauncherAppState.getInstance(this) 全拿到。类注释 @Deprecated 明确建议新代码直接 @Inject 具体依赖。
DaggerSingletonObject 包装：INSTANCE 是一个 lambda it.launcherAppState，it 是 LauncherAppComponent。getInstance(context) 调用 INSTANCE[context] 会先取 Dagger 组件（LauncherComponentProvider.get(context)，内部双重检查锁懒加载），再从组件取实例。为什么用反射拿组件？因为 ContentProvider 可能在 Application.onCreate 之前就被访问，此时必须懒加载。
和 Launcher 的关系Launcher 在 onCreate 通过 LauncherAppState.getInstance(this) 一次性拿到 mModel（LauncherModel）和 idp（InvariantDeviceProfile），之后所有操作都用这两个引用。AppState 本身不持有 Launcher，关系是单向的：Launcher → AppState（取依赖）。
面试深问为什么 LauncherAppState 是 data class 而不是普通 class？data class 自动生成 equals&#x2F;hashCode&#x2F;toString&#x2F;copy，便于测试时构造不同的依赖组合。它的字段全是 val（不可变），没有可变状态，纯依赖容器。
DaggerSingletonObject 解决什么问题？它把”从 Dagger 组件取单例”包装成静态访问（INSTANCE[context]），让 Java 代码（Launcher.java）无需改造成 @Inject 字段就能拿到 Kotlin 注入的对象。这是 Dagger 与遗留 Java 代码共存的桥接模式。
如果新代码都该直接 @Inject，为什么还保留 getInstance？兼容。Launcher3 还有很多 Java 类（LauncherProvider、LoaderTask 的部分调用路径）通过静态方式取依赖，全改造成 @Inject 工作量大且影响范围广。getInstance 保留是为了渐进迁移。
LauncherModel.kt Model 层核心LauncherModel 是 MVC 的 Model：维护内存状态（BgDataModel + AllAppsList），调度异步加载（LoaderTask），处理增量更新（ModelUpdateTask）。标 @LauncherAppSingleton，整个进程一份。
关键状态字段// LauncherModel.kt@LauncherAppSingletonclass LauncherModel @Inject constructor(...) : LauncherDumpable &#123;    private val mCallbacksList = ArrayList&lt;BgDataModel.Callbacks&gt;(1) // 注册的回调(Launcher 等)    private val mLock = Any()                                      // 所有状态字段的同步锁    private var mLoaderTask: LoaderTask? = null                    // 当前加载任务    private var mIsLoaderTaskRunning = false    private var mShouldReloadWorkProfile = true                    // 每次重启只 reload 一次工作资料    private var mModelLoaded = false                               // 数据是否已加载且有效    private var mModelDestroyed = false    fun isModelLoaded() = synchronized(mLock) &#123;        mModelLoaded &amp;&amp; mLoaderTask == null &amp;&amp; !mModelDestroyed    // 三条件全满足才算就绪    &#125;    var lastLoadId: Int = -1                                       // 加载版本号, 丢弃过期 bind 用        private set&#125;

mModelLoaded 注释明确：启动时为 false，加载完成后设 true，假设后续靠 PackageManager 监听做增量更新，不再 requery。isModelLoaded() 三个条件是”数据已加载 + 没有正在跑的 LoaderTask + 未销毁”。
addCallbacksAndLoad 快慢双路径Launcher 通过 addCallbacksAndLoad(this) 与 Model 建立关系。返回值决定走快路径（同步 bind）还是慢路径（LoaderTask 异步）。
// LauncherModel.ktfun addCallbacksAndLoad(callbacks: BgDataModel.Callbacks): Boolean &#123;    synchronized(mLock) &#123;        addCallbacks(callbacks)        return startLoader(arrayOf(callbacks))    &#125;&#125;private fun startLoader(newCallbacks: Array&lt;BgDataModel.Callbacks&gt;): Boolean &#123;    // 加载期间暂停&quot;新装 App 入桌&quot;, commit/close 时恢复    installQueue.pauseModelPush(ItemInstallQueue.FLAG_LOADER_RUNNING)    synchronized(mLock) &#123;        val wasRunning = stopLoader()                             // 停掉旧 LoaderTask        val bindDirectly = mModelLoaded &amp;&amp; !mIsLoaderTaskRunning  // 快路径条件: 已加载且无任务在跑        val bindAllCallbacks = wasRunning || !bindDirectly || newCallbacks.isEmpty()        val callbacksList = if (bindAllCallbacks) callbacks else newCallbacks        if (callbacksList.isNotEmpty()) &#123;            val launcherBinder = binderFactory.createBinder(callbacksList)            if (bindDirectly) &#123;                // 快路径: 数据已在内存, 直接同步 bind                launcherBinder.bindWorkspace(bindAllCallbacks, /* isBindSync= */ true)                launcherBinder.bindAllApps()                launcherBinder.bindWidgets()                return true                                        // 返回 true = 同步绑定成功            &#125; else &#123;                // 慢路径: 启动 LoaderTask 异步加载                val task = loaderFactory.newLoaderTask(launcherBinder)                mLoaderTask = task                // 必须 post 而非直接 run, 为了退出嵌套 synchronized 块                MODEL_EXECUTOR.post(task)            &#125;        &#125;    &#125;    return false                                                   // 返回 false = 异步加载中&#125;

快路径发生在：进程没死、数据已加载（如配置变化导致 Activity 重建）。此时 mModelLoaded == true，直接用内存数据同步 bind，无需查 DB。慢路径发生在冷启动或 forceReload 后，必须跑 LoaderTask 从头查 DB + 系统服务。
LoaderTransaction 版本号机制LoaderTask 通过 LoaderTransaction 与 Model 交互，保证状态一致。try-with-resources 包裹：
// LauncherModel.ktinner class LoaderTransaction(task: LoaderTask) : AutoCloseable &#123;    private var mTask: LoaderTask? = null    init &#123;        synchronized(mLock) &#123;            if (mLoaderTask !== task) &#123;                throw CancellationException(&quot;Loader already stopped&quot;) // 已被新任务替换, 直接取消            &#125;            this@LauncherModel.lastLoadId++                       // 加载版本号自增            mTask = task            mIsLoaderTaskRunning = true            mModelLoaded = false                                  // 加载期间数据视为无效        &#125;    &#125;    fun commit() &#123;        synchronized(mLock) &#123;            mModelLoaded = true                                   // 加载完成, 标记有效        &#125;    &#125;    override fun close() &#123;        synchronized(mLock) &#123;            if (mLoaderTask === mTask) &#123;                mLoaderTask = null                                // 清理任务引用            &#125;            mIsLoaderTaskRunning = false        &#125;    &#125;&#125;

lastLoadId 配合 BgDataModel.lastBindId 解决”快速切换网格导致 UI 数据错乱”。每次 LoaderTask 开始 lastLoadId++，bind 时把当前 lastLoadId 存入 BgDataModel.lastLoadId。若中途有新 LoaderTask 启动（lastLoadId 又变），旧任务的 bind 在 BaseLauncherBinder.executeCallbacksTask 里发现 mMyBindingId != mBgDataModel.lastBindId，直接丢弃（打印 “Too many consecutive reloads, skipping obsolete data-bind”）。
forceReload 与 rebindCallbacks// LauncherModel.ktfun forceReload() &#123;    synchronized(mLock) &#123;        stopLoader()                  // 先停旧任务, 防止它之后把 mModelLoaded 设回 true        mModelLoaded = false          // 标记数据失效    &#125;    rebindCallbacks()                 // 重启加载&#125;fun rebindCallbacks() &#123;    if (hasCallbacks()) startLoader()&#125;

LauncherProvider 外部改数据后就调 forceReload。stopLoader 的顺序很关键：必须先停旧任务再置 mModelLoaded = false，否则旧任务 commit 时会把 mModelLoaded 设回 true。
enqueueModelUpdateTask 增量更新不是所有变化都要全量重载。包安装&#x2F;卸载&#x2F;图标更新等通过 ModelUpdateTask 投到后台线程，增量改 BgDataModel 后增量 bind：
// LauncherModel.ktfun enqueueModelUpdateTask(task: ModelUpdateTask) &#123;    if (mModelDestroyed) return    MODEL_EXECUTOR.execute &#123;        if (!isModelLoaded()) &#123;            return@execute          // 必须先全量加载完, 否则丢弃(等 LoaderTask 跑完)        &#125;        task.execute(taskControllerProvider.get(), mBgDataModel, mBgAllAppsList)    &#125;&#125;fun interface ModelUpdateTask &#123;    fun execute(taskController: ModelTaskController, dataModel: BgDataModel, apps: AllAppsList)&#125;

典型 ModelUpdateTask 实现：CacheDataUpdatedTask（包图标更新）、UserAvailabilityChangedTask（工作资料可用性变化）、UserLockStateChangedTask（用户锁定&#x2F;解锁）。这些只改对应条目，比 forceReload 全量重载高效得多。
onUserEvent 用户变化分级处理// LauncherModel.kt onUserEventfun onUserEvent(user: UserHandle, action: String) &#123;    when (action) &#123;        Intent.ACTION_MANAGED_PROFILE_AVAILABLE -&gt; &#123;            if (mShouldReloadWorkProfile) &#123;                forceReload()                              // 大变化: 全量重载            &#125; else &#123;                enqueueModelUpdateTask(UserAvailabilityChangedTask(user)) // 增量            &#125;            mShouldReloadWorkProfile = false               // 每次重启只全量 reload 一次        &#125;        Intent.ACTION_MANAGED_PROFILE_UNAVAILABLE -&gt;            enqueueModelUpdateTask(UserAvailabilityChangedTask(user))        UserCache.ACTION_PROFILE_LOCKED -&gt;            enqueueModelUpdateTask(UserLockStateChangedTask(user, false))        UserCache.ACTION_PROFILE_UNLOCKED -&gt;            enqueueModelUpdateTask(UserLockStateChangedTask(user, true))        Intent.ACTION_MANAGED_PROFILE_REMOVED -&gt; &#123;            prefs.put(LauncherPrefs.WORK_EDU_STEP, 0)            forceReload()        &#125;        UserCache.ACTION_PROFILE_ADDED, UserCache.ACTION_PROFILE_REMOVED -&gt; forceReload()    &#125;&#125;

策略：资料增删&#x2F;移除走全量重载（结构变化大），锁定&#x2F;解锁&#x2F;可用性变化走增量（只改可见性）。mShouldReloadWorkProfile 保证每次设备重启只全量 reload 一次工作资料，避免重复开销。
ModelWriter 用户操作的写库入口// LauncherModel.ktfun getWriter(verifyChanges: Boolean, cellPosMapper: CellPosMapper?, owner: BgDataModel.Callbacks?) =    ModelWriter(context, this, mBgDataModel, verifyChanges, cellPosMapper, owner)

用户拖拽图标&#x2F;添加 Widget 后，Launcher 持有的 mModelWriter 调 addItemToDatabase：先在 MODEL_EXECUTOR 改内存 BgDataModel，再写 favorites 表。这是 UI → Model → DB 的反向链路。
面试深问为什么 LauncherModel 加载用 LoaderTask 而不是 LiveData&#x2F;协程？Launcher3 起步早于 Jetpack 成熟期，且加载涉及跨多个系统服务（LauncherApps&#x2F;AppWidgetManager&#x2F;ShortcutManager）、分步 bind、waitForIdle 等复杂时序，用 Runnable + Executor 更可控。LiveData 是主线程生命周期感知的响应式数据，不适合”后台构造、分步推送、版本化丢弃”这种重型流水线。协程理论上可行，但迁移成本高且老代码稳定。
LoaderTransaction 用 try-with-resources 而不是手动 commit 有什么好处？异常或取消时 close() 自动清理 mIsLoaderTaskRunning 和 mLoaderTask 引用，避免任务崩了后 Model 卡在”加载中”状态。commit() 必须显式调用——只有成功完成才置 mModelLoaded = true，中途异常不会误标已加载。
lastLoadId 为什么不直接复用 lastBindId？lastLoadId 是加载级别的版本号（每次 LoaderTask 开始自增），lastBindId 是 bind 级别的（每次 bindWorkspace(incrementBindId=true) 自增）。一次加载可能触发多次 bind（Workspace、AllApps、Widgets 分开），两个版本号粒度不同，绑定层校验用 lastBindId 更精确。
LauncherProvider + ModelDbController 数据存储LauncherProvider ContentProvider 跨进程门面LauncherProvider 是外部应用操作 Launcher 数据的唯一合法通道。类注释明确：只有系统分区应用或平台签名应用能访问。onCreate 极轻（直接返回 true），所有 CRUD 委托给 ModelDbController。
// LauncherProvider.java@Overridepublic Cursor query(Uri uri, String[] projection, String selection,        String[] selectionArgs, String sortOrder) &#123;    Pair&lt;String, String[]&gt; args = parseUri(uri, selection, selectionArgs);    Cursor[] result = new Cursor[1];    executeControllerTask(controller -&gt; &#123;        result[0] = controller.query(projection, args.first, args.second, sortOrder);        return 0;    &#125;);    return result[0];&#125;

executeControllerTask 是关键调度逻辑：
// LauncherProvider.javaprivate int executeControllerTask(ToIntFunction&lt;ModelDbController&gt; task) &#123;    if (Binder.getCallingPid() == Process.myPid()) &#123;        throw new IllegalArgumentException(&quot;Same process should call model directly&quot;);        // 同进程直接抛异常, 强制走 ModelDbController, 避免无谓 binder+线程切换开销    &#125;    try &#123;        return MODEL_EXECUTOR.submit(() -&gt; &#123;            LauncherModel model = LauncherAppState.getInstance(getContext()).getModel();            int count = task.applyAsInt(model.getModelDbController());            if (count &gt; 0) &#123;                MAIN_EXECUTOR.submit(model::forceReload);    // 数据变了, 强制重新加载+bind            &#125;            return count;        &#125;).get();                                             // 同步等结果(binder 线程)    &#125; catch (Exception e) &#123;        throw new IllegalStateException(e);    &#125;&#125;

设计精妙点：同进程拦截（强制走 Controller 省 binder 开销）、跨进程投到 MODEL_EXECUTOR（保证线程安全）、写后通知 forceReload（UI 自动更新）。
call() XML 导入导出类注释明确不推荐直接 insert/query（加载中调用会出问题、非原子），推荐用 call() 的 XML 方式：
// LauncherProvider.java@Overridepublic Bundle call(String method, String arg, Bundle extras) &#123;    Bundle b = new Bundle();    switch(method) &#123;        case METHOD_EXPORT_LAYOUT_XML:            // 校验读权限            CompletableFuture&lt;String&gt; resultFuture = LauncherComponentProvider                    .get(getContext()).getLayoutImportExportHelper().exportModelDbAsXmlFuture();            b.putString(KEY_LAYOUT, resultFuture.get());            b.putString(KEY_RESULT, SUCCESS);            return b;        case METHOD_IMPORT_LAYOUT_XML:            // 校验写权限            LauncherComponentProvider.get(getContext())                    .getLayoutImportExportHelper().importModelFromXml(arg); // 原子: 清旧+写新            b.putString(KEY_RESULT, SUCCESS);            return b;        default:            return null;    &#125;&#125;

XML 方式原子（一次清空 + 一次写入，2 次 binder 内完成）、支持自定义标签、加载中调用更安全。
ModelDbController DB 管理器// ModelDbController.java@LauncherAppSingletonpublic class ModelDbController &#123;    protected DatabaseHelper mOpenHelper;                     // SQLiteOpenHelper    @Inject    ModelDbController(Context context, InvariantDeviceProfile idp, LauncherPrefs prefs,            UserCache userCache, LayoutParserFactory layoutParserFactory,            Provider&lt;GridSizeMigrationLogic&gt; migrationLogicFactory) &#123; ... &#125;    // 懒加载打开 DB    private synchronized void createDbIfNotExists() &#123;        if (mOpenHelper == null) &#123;            Consumer&lt;ModelDbController&gt; restoreTask = RestoreDbTask.createRestoreTask(mContext);            String dbFile = mPrefs.get(DB_FILE);            if (dbFile.isEmpty()) &#123;                dbFile = mIdp.dbFile;                         // 取 IDP 指定的网格 db            &#125;            mOpenHelper = createDatabaseHelper(false, dbFile);            restoreTask.accept(this);                         // 恢复备份任务        &#125;    &#125;    @WorkerThread    public Cursor query(String[] projection, String selection,            String[] selectionArgs, String sortOrder) &#123;        createDbIfNotExists();        SQLiteDatabase db = mOpenHelper.getWritableDatabase();        Cursor result = db.query(TABLE_NAME, projection, selection, selectionArgs, null, null, sortOrder);        final Bundle extra = new Bundle();        extra.putString(EXTRA_DB_NAME, mOpenHelper.getDatabaseName()); // 把 db 名塞 Cursor extras        result.setExtras(extra);        return result;    &#125;    @WorkerThread    public int insert(ContentValues initialValues) &#123;        createDbIfNotExists();        SQLiteDatabase db = mOpenHelper.getWritableDatabase();        addModifiedTime(initialValues);                       // 自动加 modified 时间戳        int rowId = mOpenHelper.dbInsertAndCheck(db, TABLE_NAME, initialValues);        if (rowId &gt;= 0) &#123;            onAddOrDeleteOp(db);                              // 增删后清理 hybrid hotseat 备份表        &#125;        return rowId;    &#125;&#125;

所有 CRUD 都先 createDbIfNotExists() 懒加载，保证 DB 在首次访问时才打开。EXTRA_DB_NAME 通过 Cursor extras 传回当前 db 文件名，LoaderTask 用它判断是否在主 db 上做 sanitize。
默认布局加载// ModelDbController.java// 优先级: app限制 &gt; Play 提供的布局 &gt; OEM 伴侣 APK &gt; 本机默认 XML@WorkerThreadpublic synchronized void loadDefaultFavoritesIfNecessary() &#123;    createDbIfNotExists();    if (mPrefs.get(getEmptyDbCreatedKey())) &#123;                 // 仅空库才加载        LauncherWidgetHolder widgetHolder = mOpenHelper.newLauncherWidgetHolder();        try &#123;            AutoInstallsLayout loader =                    mLayoutParserFactory.createExternalLayoutParser(widgetHolder, mOpenHelper);            final boolean usingExternallyProvidedLayout = loader != null;            if (loader == null) &#123;                loader = getDefaultLayoutParser(widgetHolder); // fallback: default_workspace_*.xml            &#125;            mOpenHelper.createEmptyDB(mOpenHelper.getWritableDatabase()); // 清半恢复的脏数据            if ((mOpenHelper.loadFavorites(mOpenHelper.getWritableDatabase(), loader) &lt;= 0)                    &amp;&amp; usingExternallyProvidedLayout) &#123;                // 外部布局加载失败, 清空再加载内部默认布局                mOpenHelper.createEmptyDB(mOpenHelper.getWritableDatabase());                mOpenHelper.loadFavorites(mOpenHelper.getWritableDatabase(),                        getDefaultLayoutParser(widgetHolder));            &#125;            clearFlagEmptyDbCreated();        &#125; finally &#123;            widgetHolder.destroy();        &#125;    &#125;&#125;

网格迁移 attemptMigrateDb切换网格时，判断源&#x2F;目标网格能否迁移（GridMigrationOption.canMigrate），能则调 GridSizeMigrationLogic.migrateGrid 把旧 db 的 item 重排到新网格 db；不能迁移或迁移失败则 resetLauncherDb（清空重建）。
// ModelDbController.javapublic void attemptMigrateDb(LauncherRestoreEventLogger restoreEventLogger,        ModelDelegate modelDelegate) throws Exception &#123;    createDbIfNotExists();    if (shouldResetDb()) &#123;        resetLauncherDb(restoreEventLogger);                  // 直接重置        return;    &#125;    DatabaseHelper oldHelper = mOpenHelper;    List&lt;String&gt; existingDBs = LauncherFiles.GRID_DB_FILES.stream()            .filter(dbName -&gt; mContext.getDatabasePath(dbName).exists())            .collect(Collectors.toList());    try &#123;        DeviceGridState srcDeviceState = new DeviceGridState(mContext);        DeviceGridState destDeviceState = new DeviceGridState(mIdp);        boolean isDestNewDb = !existingDBs.contains(destDeviceState.getDbFile());        GridMigrationOption sourceGridMigrationOption = GridMigrationOption.Companion.from(                srcDeviceState.getColumns(), srcDeviceState.getRows());        GridMigrationOption destinationGridMigrationOption = GridMigrationOption.Companion.from(                destDeviceState.getColumns(), destDeviceState.getRows());        if (sourceGridMigrationOption != null &amp;&amp; destinationGridMigrationOption != null                &amp;&amp; sourceGridMigrationOption.canMigrate(destinationGridMigrationOption, isAfterRestore)) &#123;            mOpenHelper = createDatabaseHelper(true, new DeviceGridState(mIdp).getDbFile());            gridSizeMigrationLogic.migrateGrid(srcDeviceState, destDeviceState,                    mOpenHelper, oldHelper.getWritableDatabase(), isDestNewDb, modelDelegate);        &#125;    &#125; catch (Exception e) &#123;        resetLauncherDb(restoreEventLogger);        throw new Exception(&quot;attemptMigrateDb: Failed to migrate grid&quot;, e);    &#125; finally &#123;        if (mOpenHelper != oldHelper) &#123;            oldHelper.close();        &#125;    &#125;&#125;

数据清洗保持一致性ModelDbController 提供三个清洗方法，保证 favorites 表引用完整性：
// ModelDbController.java// 删除没有子 item 的空文件夹public IntArray deleteEmptyFolders() &#123;    // SELECT _id WHERE itemType=FOLDER AND _id NOT IN (SELECT container FROM favorites)&#125;// 删除成员数 ≠ 2 的 App Pairpublic IntArray deleteBadAppPairs() &#123;    // SELECT _id WHERE itemType=APP_PAIR AND _id NOT IN    //   (SELECT container FROM favorites GROUP BY container HAVING COUNT(*) = 2)&#125;// 删除 container 指向不存在文件夹的孤儿 apppublic IntArray deleteUnparentedApps() &#123;    // SELECT _id WHERE container &gt;= 0 AND container NOT IN (SELECT _id FROM favorites)&#125;

favorites 表 Schemafavorites 是唯一用户数据表，每行 &#x3D; 桌面一个 item。建表 SQL 由 LauncherSettings.Favorites.addTableToDb 生成，列定义在 getColumnsToTypes：
// LauncherSettings.javapublic static void addTableToDb(SQLiteDatabase db, long myProfileId, boolean optional,        String tableName) &#123;    db.execSQL(&quot;CREATE TABLE &quot; + (optional ? &quot; IF NOT EXISTS &quot; : &quot;&quot;) + tableName + &quot; (&quot;            + getJoinedColumnsToTypes(myProfileId) + &quot;);&quot;);&#125;@NonNullprivate static LinkedHashMap&lt;String, String&gt; getColumnsToTypes(long profileId) &#123;    final LinkedHashMap&lt;String, String&gt; columnsToTypes = new LinkedHashMap&lt;&gt;();    columnsToTypes.put(_ID, &quot;INTEGER PRIMARY KEY&quot;);    columnsToTypes.put(TITLE, &quot;TEXT&quot;);    columnsToTypes.put(INTENT, &quot;TEXT&quot;);              // 启动 Intent (URI 形式)    columnsToTypes.put(CONTAINER, &quot;INTEGER&quot;);        // 容器(桌面/Hotseat/文件夹ID)    columnsToTypes.put(SCREEN, &quot;INTEGER&quot;);           // 所在屏幕页(Hotseat 下=rank)    columnsToTypes.put(CELLX, &quot;INTEGER&quot;);            // 单元格 X    columnsToTypes.put(CELLY, &quot;INTEGER&quot;);            // 单元格 Y    columnsToTypes.put(SPANX, &quot;INTEGER&quot;);            // X 跨度(Widget 用)    columnsToTypes.put(SPANY, &quot;INTEGER&quot;);            // Y 跨度    columnsToTypes.put(ITEM_TYPE, &quot;INTEGER&quot;);        // item 类型    columnsToTypes.put(APPWIDGET_ID, &quot;INTEGER NOT NULL DEFAULT -1&quot;);    columnsToTypes.put(ICON, &quot;BLOB&quot;);                // 自定义图标二进制    columnsToTypes.put(APPWIDGET_PROVIDER, &quot;TEXT&quot;);  // Widget provider ComponentName    columnsToTypes.put(MODIFIED, &quot;INTEGER NOT NULL DEFAULT 0&quot;);    columnsToTypes.put(RESTORED, &quot;INTEGER NOT NULL DEFAULT 0&quot;);    columnsToTypes.put(PROFILE_ID, &quot;INTEGER DEFAULT &quot; + profileId); // 多用户/工作资料    columnsToTypes.put(RANK, &quot;INTEGER NOT NULL DEFAULT 0&quot;);         // 文件夹内/hotseat 顺序    columnsToTypes.put(OPTIONS, &quot;INTEGER NOT NULL DEFAULT 0&quot;);      // 通用 flag 位    columnsToTypes.put(APPWIDGET_SOURCE, &quot;INTEGER NOT NULL DEFAULT -1&quot;); // Widget 来源容器    return columnsToTypes;&#125;

用 LinkedHashMap 保持列插入顺序，getJoinedColumnsToTypes 拼成 &quot;col1 type1, col2 type2, ...&quot;。
